            log.warn("Sender ikke annuleringsmelding for tilskuddsperiode {} med utgått refusjon.", tilskuddsperiode.getId());
        } else {
            tilskuddsperiode.setStatus(TilskuddPeriodeStatus.ANNULLERT);
