@UtilityClass
public class StartOgSluttDatoStrategyFactory {
    public static StartOgSluttDatoStrategy create(Tiltakstype tiltakstype, Kvalifiseringsgruppe kvalifiseringsgruppe) {
        switch (tiltakstype) {
            case ARBEIDSTRENING:
                return new ArbeidstreningStartOgSluttDatoStrategy();
            case MIDLERTIDIG_LONNSTILSKUDD:
                return new MidlertidigLonnstilskuddStartOgSluttDatoStrategy(kvalifiseringsgruppe);
            case VARIG_LONNSTILSKUDD:
                return new VarigLonnstilskuddStartOgSluttDatoStrategy();
            case MENTOR:
                return new MentorStartOgSluttDatoStrategy(kvalifiseringsgruppe);
            case INKLUDERINGSTILSKUDD:
                return new InkluderingstilskuddStartOgSluttDatoStrategy();
            case SOMMERJOBB:
                return new SommerjobbStartOgSluttDatoStrategy();
        }
        return new StartOgSluttDatoStrategy() {
        };
    }
}

public enum Formidlingsgruppe {
    ARBEIDSSOKER("ARBS"),            // Person er tilgjengelig for alt søk etter   arbeidskraft, ordinær og vikar
    IKKE_ARBEIDSSOKER("IARBS"),      // Person er ikke tilgjengelig for søk etter arbeidskraft
    INAKTIVERT_JOBBSKIFTER("IJOBS"), // Jobbskifter som er inaktivert fra nav.no
    IKKE_SERVICEBEHOV("ISERV"),      // Inaktivering, person mottar ikke bistand fra NAV
    FRA_NAV_NO("JOBBS"),             // Personen er ikke tilgjengelig for søk
    PRE_ARBEIDSSOKER("PARBS"),       // Personen fra nav.no som ønsker å bli arbeidssøker, men som enda ikke er   verifisert
    PRE_REAKTIVERT_ARBEIDSSOKER("RARBS"); //Person som er reaktivert fra nav.no
    private final String formidlingskode;

    Formidlingsgruppe(String formidlingskode) { this.formidlingskode = formidlingskode; }

    @JsonValue
    public String getKode() {
        return formidlingskode;
    }

    public static boolean ugyldigFormidlingsgruppe(Formidlingsgruppe formidlingsgruppe) {
        return switch (formidlingsgruppe) {
            case IKKE_ARBEIDSSOKER, INAKTIVERT_JOBBSKIFTER, IKKE_SERVICEBEHOV -> true;
            case ARBEIDSSOKER, FRA_NAV_NO, PRE_ARBEIDSSOKER, PRE_REAKTIVERT_ARBEIDSSOKER -> false;
        };
    }
}

@Slf4j
public enum Kvalifiseringsgruppe {
    SPESIELT_TILPASSET_INNSATS("BATT"),      // Personen har nedsatt arbeidsevne og har et identifisert behov for kvalifisering og/eller tilrettelegging. Aktivitetsplan skal utformes.
    SITUASJONSBESTEMT_INNSATS("BFORM"),      // Personen har moderat bistandsbehov
    VARIG_TILPASSET_INNSATS("VARIG"),        // Personen har varig nedsatt arbeidsevne
    BEHOV_FOR_ARBEIDSEVNEVURDERING("BKART"), // Personen har behov for arbeidsevnevurdering
    STANDARD_INNSATS("IKVAL"),               // Personen har behov for ordinær bistand
    IKKE_VURDERT("IVURD"),                   // Ikke vurdert
    RETTIGHETER_ETTER_FTRL_KAP11("KAP11"),   // Rettigheter etter Ftrl. Kapittel 11
    HELSERELATERT_ARBEIDSRETTET_OPPFOLGING_I_NAV("OPPFI"), // Helserelatert arbeidsrettet oppfølging i NAV
    SYKMELDT_OPPFOLGING_PA_ARBEIDSPLASSEN("VURDI"),        // Sykmeldt, oppfølging på arbeidsplassen
    SYKMELDT_UTEN_ARBEIDSGIVER("VURDU");                   // Sykmeldt uten arbeidsgiver


    private final String kvalifiseringskode;

    Kvalifiseringsgruppe(String kvalifiseringskode) {
        this.kvalifiseringskode = kvalifiseringskode;
    }

    @JsonValue
    public String getKvalifiseringskode() {
        return kvalifiseringskode;
    }

    public static boolean ugyldigKvalifiseringsgruppe(Kvalifiseringsgruppe kvalifiseringsgruppe) {
        return switch (kvalifiseringsgruppe) {
            case STANDARD_INNSATS, BEHOV_FOR_ARBEIDSEVNEVURDERING, IKKE_VURDERT -> true;
            case RETTIGHETER_ETTER_FTRL_KAP11, HELSERELATERT_ARBEIDSRETTET_OPPFOLGING_I_NAV,
                    SYKMELDT_OPPFOLGING_PA_ARBEIDSPLASSEN, SYKMELDT_UTEN_ARBEIDSGIVER,
                    SPESIELT_TILPASSET_INNSATS, SITUASJONSBESTEMT_INNSATS, VARIG_TILPASSET_INNSATS -> false;
        };
    }

    public static boolean kvalifisererTilMidlertidiglonnstilskuddOgSommerjobbOgMentor(Kvalifiseringsgruppe kvalifiseringsgruppe) {
        return switch (kvalifiseringsgruppe) {
            case SPESIELT_TILPASSET_INNSATS, SITUASJONSBESTEMT_INNSATS, VARIG_TILPASSET_INNSATS -> true;
            default -> false;
        };
    }

    public static boolean kvalifisererTilVariglonnstilskudd(Kvalifiseringsgruppe kvalifiseringsgruppe) {
        return kvalifiseringsgruppe == VARIG_TILPASSET_INNSATS;
    }

    public Integer finnLonntilskuddProsentsatsUtifraKvalifiseringsgruppe(Integer prosentsatsLiten, Integer prosentsatsStor) {
        switch (this) {
            case SPESIELT_TILPASSET_INNSATS, VARIG_TILPASSET_INNSATS:
                return prosentsatsStor;
            case SITUASJONSBESTEMT_INNSATS:
                return prosentsatsLiten;
            default: {
                log.warn("feilet med setting av kvalifiseringsgruppe. Kvalifiseringsgruppe: {}", this);
                return null;
            }
        }
    }
}

@Value
public class Navn {
    public static final Navn TOMT_NAVN = new Navn("", "", "");
    private final String fornavn;
    private final String mellomnavn;
    private final String etternavn;
}

public class NavnFormaterer {
    private final Navn navn;

    public NavnFormaterer(Navn navn) {
        this.navn = navn;
    }

    public String getEtternavn() {
        return storeForbokstaver(navn.getEtternavn());
    }

    public String getFornavn() {
        String fornavnOgMellomnavn = navn.getFornavn();
        if (StringUtils.hasLength(navn.getMellomnavn())) {
            fornavnOgMellomnavn += " " + navn.getMellomnavn();
        }
        return storeForbokstaver(fornavnOgMellomnavn);
    }

    private static String storeForbokstaver(String navn) {
        return WordUtils.capitalizeFully(navn, '-', ' ');
    }
}

public class Now {
    private static ThreadLocal<Clock> clock = ThreadLocal.withInitial(Clock::systemDefaultZone);

    public static void fixedDate(LocalDate localDate) {
        Instant instant = ZonedDateTime.of(localDate.atStartOfDay(), ZoneId.systemDefault()).toInstant();
        clock.set(Clock.fixed(instant, ZoneId.systemDefault()));
    }

    public static void resetClock() {
        Now.clock.set(Clock.systemDefaultZone());
    }

    public static Instant instant() {
        return Instant.now(clock.get());
    }

    public static LocalDate localDate() {
        return LocalDate.now(clock.get());
    }

    public static LocalDateTime localDateTime() {
        return LocalDateTime.now(clock.get());
    }

    public static YearMonth yearMonth() {
        return YearMonth.now(clock.get());
    }
}

@UtilityClass
public class
TelefonnummerValidator {
    public static boolean erGyldigMobilnummer(String tlf) {
        if (tlf == null) {
            return false;
        }
        return tlf.matches("[4|9][0-9]{7}");
    }
}

@UtilityClass
public class Utils {
    public static <T> T sjekkAtIkkeNull(T in, String feilmelding) {
        if (in == null) {
            throw new TiltaksgjennomforingException(feilmelding);
        }
        return in;
    }

    public static boolean erIkkeTomme(Object... objekter) {
        for (Object objekt : objekter) {
            if (objekt instanceof String && ((String) objekt).isEmpty()) {
                return false;
            }
            if (objekt instanceof Collection && ((Collection<?>) objekt).isEmpty()) {
                return false;
            }
            if (objekt == null) {
                return false;
            }
        }
        return true;
    }

    public static boolean erNoenTomme(Object... objekter) {
        return !erIkkeTomme(objekter);
    }

    public static boolean erTom(Object objekt) {
        return !erIkkeTomme(objekt);
    }

    public static URI lagUri(String path) {
        return UriComponentsBuilder
                .fromPath(path)
                .build()
                .toUri();
    }

    public static void sjekkAtTekstIkkeOverskrider1000Tegn(String tekst, String feilmelding) {
        if ((tekst != null) && tekst.length() > 1000) {
            throw new TiltaksgjennomforingException(feilmelding);
        }
    }
}

