public class AlleredeRegistrertAvtale {

    private UUID id;
    private Integer avtaleNr;
    private Tiltakstype tiltakstype;
    private Fnr deltakerFnr;
    private BedriftNr bedriftNr;
    private NavIdent veilederNavIdent;
    private Status status;
