        var rettede = tilskuddPeriode.stream()
                .filter(TilskuddPeriode::isAktiv)
                .filter(t -> t.getStatus() == TilskuddPeriodeStatus.AVSLÅTT)
                .map(TilskuddPeriode::deaktiverOgLagNyUbehandlet).toList();
        tilskuddPeriode.addAll(rettede);
    }

