        final Norg2OppfølgingResponse response = norg2Client.hentOppfølgingsEnhetsnavnFraCacheNorg2(
                avtale.getEnhetOppfolging()
        );
        if (response == null) return;
        avtale.setEnhetsnavnOppfolging(response.getNavn());
    }

