@Component
@RequiredArgsConstructor
@Slf4j
public class InnloggingService {
    private final SystembrukerProperties systembrukerProperties;
    private final BeslutterAdGruppeProperties beslutterAdGruppeProperties;
    private final TokenUtils tokenUtils;
    private final AltinnTilgangsstyringService altinnTilgangsstyringService;
    private final TilgangskontrollService tilgangskontrollService;
    private final PersondataService persondataService;
    private final Norg2Client norg2Client;
    private final AxsysService axsysService;
    private final SlettemerkeProperties slettemerkeProperties;
    private final VeilarbArenaClient veilarbArenaClient;
    private final ArbeidsgiverTokenStrategyFactory arbeidsgiverTokenStrategyFactory;

    public Avtalepart hentAvtalepart(Avtalerolle avtalerolle) {
        BrukerOgIssuer brukerOgIssuer = tokenUtils.hentBrukerOgIssuer().orElseThrow(() -> new TilgangskontrollException("Bruker er ikke innlogget."));
        Issuer issuer = brukerOgIssuer.getIssuer();

        if (issuer == Issuer.ISSUER_TOKENX && (avtalerolle == Avtalerolle.DELTAKER || avtalerolle == Avtalerolle.MENTOR)) {
            if(avtalerolle == Avtalerolle.DELTAKER) return new Deltaker(new Fnr(brukerOgIssuer.getBrukerIdent()));
            else return new Mentor(new Fnr(brukerOgIssuer.getBrukerIdent()));
        }else if (issuer == Issuer.ISSUER_TOKENX && avtalerolle == Avtalerolle.ARBEIDSGIVER) {
            HentArbeidsgiverToken hentArbeidsgiverToken = arbeidsgiverTokenStrategyFactory.create(issuer);

            Set<AltinnReportee> altinnOrganisasjoner = altinnTilgangsstyringService
                    .hentAltinnOrganisasjoner(new Fnr(brukerOgIssuer.getBrukerIdent()), hentArbeidsgiverToken);
            Map<BedriftNr, Collection<Tiltakstype>> tilganger = altinnTilgangsstyringService.hentTilganger(new Fnr(brukerOgIssuer.getBrukerIdent()), hentArbeidsgiverToken);
            return new Arbeidsgiver(new Fnr(brukerOgIssuer.getBrukerIdent()), altinnOrganisasjoner, tilganger, persondataService, norg2Client);
        } else if (issuer == Issuer.ISSUER_AAD && avtalerolle == Avtalerolle.VEILEDER) {
            NavIdent navIdent = new NavIdent(brukerOgIssuer.getBrukerIdent());
            Set<NavEnhet> navEnheter = hentNavEnheter(navIdent);
            boolean harAdGruppeForBeslutter = tokenUtils.harAdGruppe(beslutterAdGruppeProperties.getId());
            return new Veileder(navIdent, tokenUtils.hentAzureOid(), tilgangskontrollService, persondataService, norg2Client, navEnheter, slettemerkeProperties, harAdGruppeForBeslutter, veilarbArenaClient);
        } else if (issuer == Issuer.ISSUER_AAD && avtalerolle == Avtalerolle.BESLUTTER) {
            boolean harAdGruppeForBeslutter = tokenUtils.harAdGruppe(beslutterAdGruppeProperties.getId());
            if (harAdGruppeForBeslutter) {
                var navIdent = new NavIdent(brukerOgIssuer.getBrukerIdent());
                var navEnheter = hentNavEnheter(navIdent);
                return new Beslutter(navIdent, tokenUtils.hentAzureOid(), navEnheter, tilgangskontrollService, norg2Client);
            } else {
                throw new FeilkodeException(Feilkode.MANGLER_AD_GRUPPE_BESLUTTER);
            }
        } else {
            log.warn("Ugyldig kombinasjon av issuer={} og rolle={}", issuer, avtalerolle);
            throw new FeilkodeException(Feilkode.UGYLDIG_KOMBINASJON_AV_ISSUER_OG_ROLLE);
        }
    }

    private Set<NavEnhet> hentNavEnheter(NavIdent navIdent) {
        return new HashSet<>(axsysService.hentEnheterNavAnsattHarTilgangTil(navIdent));
    }

    public Veileder hentVeileder() {
        return (Veileder) hentAvtalepart(Avtalerolle.VEILEDER);
    }

    public Arbeidsgiver hentArbeidsgiver() {
        return (Arbeidsgiver) hentAvtalepart(Avtalerolle.ARBEIDSGIVER);
    }

    public InnloggetBruker hentInnloggetBruker(Avtalerolle avtalerolle) {
        return hentAvtalepart(avtalerolle).innloggetBruker();
    }

    public InnloggetVeileder hentInnloggetVeileder() {
        try {
            return (InnloggetVeileder) hentInnloggetBruker(Avtalerolle.VEILEDER);
        } catch (ClassCastException e) {
            throw new TilgangskontrollException("Innlogget bruker er ikke veileder.");
        }
    }

    public void validerSystembruker() {
        tokenUtils.hentBrukerOgIssuer()
                .filter(t -> (Issuer.ISSUER_SYSTEM == t.getIssuer() && systembrukerProperties.getId().equals(t.getBrukerIdent())))
                .orElseThrow(() -> new TilgangskontrollException("Systemet har ikke tilgang til tjenesten"));
    }

    public Beslutter hentBeslutter() {
        return (Beslutter) hentAvtalepart(Avtalerolle.BESLUTTER);
    }
}

@Service
@RequiredArgsConstructor
@Slf4j
public class DokgenService {
    private static final BigDecimal HUNDRE = new BigDecimal("100");

    private final DokgenProperties dokgenProperties;
    private final MeterRegistry meterRegistry;

    public byte[] avtalePdf(Avtale avtale, Avtalerolle avtalerolle) {
        var avtaleTilJournalfoering = AvtaleTilJournalfoeringMapper.tilJournalfoering(avtale.getGjeldendeInnhold(), avtalerolle);
        gangOppSatserMed100(avtaleTilJournalfoering);
        fjernGodkjentPåVegneAv(avtaleTilJournalfoering);
        try {
            byte[] bytes = restOperations().postForObject(dokgenProperties.getUri(), avtaleTilJournalfoering, byte[].class);
            meterRegistry.counter("tiltaksgjennomforing.pdf.ok").increment();
            return bytes;
        } catch (RestClientException e) {
            log.error("Feil ved kall til dokgen for henting av PDF", e);
            meterRegistry.counter("tiltaksgjennomforing.pdf.feil").increment();
            throw e;
        }
    }

    // TODO: Det bør heller ganges med 100 fra starten av i AvtaleTilJournalfoering.
    //  Slik som det er nå så gjøres det ganging med 100 både her og i tiltaksgjennomforing-prosess.
    //  Endring på dette krever en synkronisert fiks både her og i tiltaksgjennomforing-prosess.
    private void gangOppSatserMed100(no.nav.tag.tiltaksgjennomforing.journalfoering.AvtaleTilJournalfoering avtaleTilJournalfoering) {
        if (avtaleTilJournalfoering.getArbeidsgiveravgift() != null) {
            avtaleTilJournalfoering.setArbeidsgiveravgift(avtaleTilJournalfoering.getArbeidsgiveravgift().multiply(HUNDRE));
        }
        if (avtaleTilJournalfoering.getFeriepengesats() != null) {
            avtaleTilJournalfoering.setFeriepengesats(avtaleTilJournalfoering.getFeriepengesats().multiply(HUNDRE));
        }
        if (avtaleTilJournalfoering.getOtpSats() != null) {
            avtaleTilJournalfoering.setOtpSats(avtaleTilJournalfoering.getOtpSats() * 100);
        }
    }

    private void fjernGodkjentPåVegneAv(no.nav.tag.tiltaksgjennomforing.journalfoering.AvtaleTilJournalfoering avtaleTilJournalfoering) {
        avtaleTilJournalfoering.setGodkjentPaVegneAv(false);
        avtaleTilJournalfoering.setGodkjentPaVegneGrunn(null);
    }

    // Lager ny instans av RestOperations i stedet for å wire inn RestTemplate fordi det var vanskelig å få den til å bruke en ObjectMapper som hadde datoer på format 'yyyy-MM-dd' i stedet for et array
    private RestOperations restOperations() {
        RestTemplate rest = new RestTemplate();
        //this is crucial!
        rest.getMessageConverters().add(0, mappingJacksonHttpMessageConverter());
        return rest;
    }

    private MappingJackson2HttpMessageConverter mappingJacksonHttpMessageConverter() {
        var converter = new MappingJackson2HttpMessageConverter();
        converter.setObjectMapper(objectMapper());
        return converter;
    }

    private ObjectMapper objectMapper() {
        var mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());
        mapper.disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        return mapper;
    }
}

@Slf4j
@Component
@AllArgsConstructor
public class Norg2Client {

    private final Norg2GeografiskProperties norg2GeografiskProperties;
    private final Norg2OppfølgingProperties norg2OppfølgingProperties;
    private final RestTemplate restTemplate;

    @Cacheable(EhCacheConfig.NORGNAVN_CACHE)
    public Norg2OppfølgingResponse hentOppfølgingsEnhetsnavnFraCacheNorg2(String enhet) {
        return this.hentOppfølgingsEnhetsnavn(enhet);
    }

    @Cacheable(EhCacheConfig.NORG_GEO_ENHET)
    public Norg2GeoResponse hentGeoEnhetFraCacheEllerNorg2(String geoTilknytning) {
        return this.hentGeografiskEnhet(geoTilknytning);
    }


    public Norg2GeoResponse hentGeografiskEnhet(String geoOmråde) {
        Norg2GeoResponse norg2GeoResponse;
        try {
            norg2GeoResponse = restTemplate.getForObject(norg2GeografiskProperties.getUrl() + geoOmråde, Norg2GeoResponse.class);
            if (norg2GeoResponse.getEnhetNr() == null) {
                log.warn("Fant ikke enhet med geoOmråde {}", geoOmråde);
            }
        } catch (Exception e) {
            log.error("Feil v/oppslag på geoOmråde {}", geoOmråde);
            throw e;
        }
        return norg2GeoResponse;
    }

    public Norg2OppfølgingResponse hentOppfølgingsEnhetsnavn(String enhet) {
        Norg2OppfølgingResponse norg2OppfølgingResponse = null;
        try {
            norg2OppfølgingResponse = restTemplate.getForObject(norg2OppfølgingProperties.getUrl() + enhet, Norg2OppfølgingResponse.class);
            if (Objects.requireNonNull(norg2OppfølgingResponse).getNavn() == null) {
                log.warn("Fant ingen navn til enhet: {}", enhet);
            }
        }catch (Exception e) {
            log.error("Feil v/oppslag på enhet {}", enhet);
        }
        return norg2OppfølgingResponse;
    }
}

@Slf4j
@Service
public class VeilarbArenaClient {

    private final RestTemplate restTemplate;
    private final VeilarbArenaProperties veilarbArenaProperties;

    public VeilarbArenaClient(
            @Qualifier("veilarbarenaRestTemplate") RestTemplate restTemplate,
            VeilarbArenaProperties veilarbArenaProperties
    ) {
        this.restTemplate = restTemplate;
        this.veilarbArenaProperties = veilarbArenaProperties;
    }

    private boolean erMidlerTidiglonnstilskuddEllerSommerjobbEllerMentor(Tiltakstype tiltakstype) {
        return (tiltakstype == Tiltakstype.SOMMERJOBB ||
                tiltakstype == Tiltakstype.MIDLERTIDIG_LONNSTILSKUDD) ||
                tiltakstype == Tiltakstype.MENTOR;
    }

    private boolean erVariglonnstilskudd(Tiltakstype tiltakstype) {
        return tiltakstype.equals(Tiltakstype.VARIG_LONNSTILSKUDD);
    }

    public Oppfølgingsstatus sjekkOgHentOppfølgingStatus(Avtale avtale) {
        Oppfølgingsstatus oppfølgingStatus = hentOppfølgingStatus(avtale.getDeltakerFnr().asString());
        if (avtale.getTiltakstype() != Tiltakstype.SOMMERJOBB) {
            sjekkStatus(avtale, oppfølgingStatus);
        }
        return oppfølgingStatus;
    }

    public void sjekkOppfølingStatus(Avtale avtale) {
        Oppfølgingsstatus oppfølgingStatus = hentOppfølgingStatus(avtale.getDeltakerFnr().asString());
        sjekkStatus(avtale, oppfølgingStatus);
    }

    private void sjekkStatus(Avtale avtale, Oppfølgingsstatus oppfølgingStatus) {
        if (
                oppfølgingStatus == null ||
                        oppfølgingStatus.getFormidlingsgruppe() == null ||
                        oppfølgingStatus.getKvalifiseringsgruppe() == null
        ) {
            throw new FeilkodeException(Feilkode.HENTING_AV_INNSATS_BEHOV_FEILET);
        }

        if (Kvalifiseringsgruppe.ugyldigKvalifiseringsgruppe(oppfølgingStatus.getKvalifiseringsgruppe())) {
            throw new FeilkodeException(Feilkode.KVALIFISERINGSGRUPPE_IKKE_RETTIGHET);
        }

        if (erMidlerTidiglonnstilskuddEllerSommerjobbEllerMentor(avtale.getTiltakstype()) &&
                !Kvalifiseringsgruppe.kvalifisererTilMidlertidiglonnstilskuddOgSommerjobbOgMentor(oppfølgingStatus.getKvalifiseringsgruppe())) {
            throw new FeilkodeException(Feilkode.KVALIFISERINGSGRUPPE_MIDLERTIDIG_LONNTILSKUDD_OG_SOMMERJOBB_FEIL);
        }

        if (erVariglonnstilskudd(avtale.getTiltakstype()) &&
                !Kvalifiseringsgruppe.kvalifisererTilVariglonnstilskudd(oppfølgingStatus.getKvalifiseringsgruppe())) {
            throw new FeilkodeException(Feilkode.KVALIFISERINGSGRUPPE_VARIG_LONNTILSKUDD_FEIL);
        }
    }

    @Cacheable(EhCacheConfig.ARENA_CACHCE)
    public Oppfølgingsstatus HentOppfølgingsenhetFraCacheEllerArena(String fnr) {
        return this.hentOppfølgingStatus(fnr);
    }

    public String hentOppfølgingsEnhet(String fnr) {
        Oppfølgingsstatus oppfølgingsstatus = hentOppfølgingStatus(fnr);
        if (oppfølgingsstatus != null) {
            return oppfølgingsstatus.getOppfolgingsenhet();
        }
        return null;
    }

    public Oppfølgingsstatus hentOppfølgingStatus(String fnr) {
        String uri = UriComponentsBuilder.fromHttpUrl(veilarbArenaProperties.getUrl().toString())
                .queryParam("fnr", fnr).toUriString();
        try {
            ResponseEntity<Oppfølgingsstatus> respons = restTemplate.exchange(
                    uri,
                    HttpMethod.GET,
                    httpHeadere(),
                    Oppfølgingsstatus.class
            );
            return respons.getBody();
        } catch (RestClientResponseException exception) {
            if (exception.getRawStatusCode() == HttpStatus.NOT_FOUND.value() &&
                    !exception.getResponseBodyAsString().isEmpty()) {
                log.warn("Kandidat ikke registrert i veilarbarena");
                return null;
            }
            log.error("Kunne ikke hente Oppfølgingsstatus fra veilarbarena: status=" +
                    exception.getRawStatusCode(), exception);
            return null;
        }
    }

    private HttpEntity<String> httpHeadere() {
        HttpHeaders headers = new HttpHeaders();
        headers.set("Nav-Consumer-Id", veilarbArenaProperties.getNavConsumerId());
        return new HttpEntity<>(headers);
    }
}

