        innhold.setInnholdType(AvtaleInnholdType.INNGÅ);
        if (tiltakstype == Tiltakstype.SOMMERJOBB) {
            innhold.setStillingstype(Stillingstype.MIDLERTIDIG);
        }
        return innhold;
