@Slf4j
@UtilityClass
public class RegnUtTilskuddsperioderForAvtale {

    private final static BigDecimal DAGER_I_MÅNED = new BigDecimal("30.4375");
    private final static int ANTALL_MÅNEDER_I_EN_PERIODE = 1;

    /**
        TODO: TODO: Kalkulering av redusert prosent og redusert dato bør kun skje i {@link no.nav.tag.tiltaksgjennomforing.avtale.VarigLonnstilskuddStrategy} og heller ikke i frontend
     */
    public static List<TilskuddPeriode> beregnTilskuddsperioderForAvtale(UUID id, Tiltakstype tiltakstype, Integer sumLønnstilskuddPerMåned, LocalDate datoFraOgMed, LocalDate datoTilOgMed, Integer lonnstilskuddprosent, LocalDate datoForRedusertProsent, Integer sumLønnstilskuddPerMånedRedusert) {
        if (datoForRedusertProsent == null) {
            // Ingen reduserte peridoder   -----60-----60------60------ |
            return lagPeriode(datoFraOgMed, datoTilOgMed).stream().map(datoPar -> {
                Integer beløp = beløpForPeriode(datoPar.getStart(), datoPar.getSlutt(), sumLønnstilskuddPerMåned);
                return new TilskuddPeriode(beløp, datoPar.getStart(), datoPar.getSlutt(), lonnstilskuddprosent);
            }).collect(Collectors.toList());
        } else {
            if (datoFraOgMed.isBefore(datoForRedusertProsent.plusDays(1)) && datoTilOgMed.isAfter(datoForRedusertProsent.minusDays(1))) {
                // Både ikke reduserte og reduserte   ---60---60-----50----|--50----50-----
                List<TilskuddPeriode> tilskuddperioderFørRedusering = lagPeriode(datoFraOgMed, datoForRedusertProsent.minusDays(1)).stream().map(datoPar -> {
                    Integer beløp = beløpForPeriode(datoPar.getStart(), datoPar.getSlutt(), sumLønnstilskuddPerMåned);
                    return new TilskuddPeriode(beløp, datoPar.getStart(), datoPar.getSlutt(), lonnstilskuddprosent);
                }).collect(Collectors.toList());

                List<TilskuddPeriode> tilskuddperioderEtterRedusering = lagPeriode(datoForRedusertProsent, datoTilOgMed).stream().map(datoPar -> {
                    Integer beløp = beløpForPeriode(datoPar.getStart(), datoPar.getSlutt(), sumLønnstilskuddPerMånedRedusert);
                    return new TilskuddPeriode(beløp, datoPar.getStart(), datoPar.getSlutt(), getLonnstilskuddProsent(tiltakstype, lonnstilskuddprosent));
                }).collect(Collectors.toList());

                ArrayList<TilskuddPeriode> tilskuddsperioder = new ArrayList<>();
                tilskuddsperioder.addAll(tilskuddperioderFørRedusering);
                tilskuddsperioder.addAll(tilskuddperioderEtterRedusering);
                return tilskuddsperioder;
            } else if (datoFraOgMed.isAfter(datoForRedusertProsent)) {
                // Kun redusete peridoer      ---60----60----60---50---|--50----50---50--50--
                List<TilskuddPeriode> tilskuddperioderEtterRedusering = lagPeriode(datoFraOgMed, datoTilOgMed).stream().map(datoPar -> {
                    Integer beløp = beløpForPeriode(datoPar.getStart(), datoPar.getSlutt(), sumLønnstilskuddPerMånedRedusert);
                    return new TilskuddPeriode(beløp, datoPar.getStart(), datoPar.getSlutt(), getLonnstilskuddProsent(tiltakstype, lonnstilskuddprosent));
                }).collect(Collectors.toList());
                ArrayList<TilskuddPeriode> tilskuddsperioder = new ArrayList<>();
                tilskuddsperioder.addAll(tilskuddperioderEtterRedusering);
                return tilskuddsperioder;
            } else {
                log.error("Uventet feil i utregning av tilskuddsperioder med startdato: {}, sluttdato: {}, datoForRedusertProsent: {}, avtaleId: {}", datoFraOgMed, datoTilOgMed, datoForRedusertProsent, id);
                throw new FeilkodeException(Feilkode.FORLENG_MIDLERTIDIG_IKKE_TILGJENGELIG);
            }
        }

    }

    private static int getLonnstilskuddProsent(Tiltakstype tiltakstype, Integer lonnstilskuddprosent) {
        if(tiltakstype == Tiltakstype.VARIG_LONNSTILSKUDD){
            if(lonnstilskuddprosent >= 68) return 67;
            return lonnstilskuddprosent;
        }
        return lonnstilskuddprosent - 10;
    }

    public static Integer beløpForPeriode(LocalDate datoFraOgMed, LocalDate datoTilOgMed, LocalDate datoForRedusertProsent, Integer sumLønnstilskuddPerMåned, Integer sumLønnstilskuddPerMånedRedusert) {
        if (datoForRedusertProsent == null || datoTilOgMed.isBefore(datoForRedusertProsent)) {
            return beløpForPeriode(datoFraOgMed, datoTilOgMed, sumLønnstilskuddPerMåned);
        } else {
            return beløpForPeriode(datoFraOgMed, datoTilOgMed, sumLønnstilskuddPerMånedRedusert);
        }
    }

    public static Integer beløpForPeriode(LocalDate fra, LocalDate til, Integer sumLønnstilskuddPerMåned) {
        Period period = Period.between(fra, til.plusDays(1));
        Integer sumHeleMåneder = period.getMonths() * sumLønnstilskuddPerMåned;
        BigDecimal dagsats = new BigDecimal(sumLønnstilskuddPerMåned).divide(DAGER_I_MÅNED, 10, RoundingMode.HALF_UP);
        Integer sumEnkeltdager = dagsats.multiply(BigDecimal.valueOf(period.getDays()), MathContext.UNLIMITED).setScale(0, RoundingMode.HALF_UP).intValue();
        return sumHeleMåneder + sumEnkeltdager;
    }

    private static List<Periode> lagPeriode(LocalDate datoFraOgMed, LocalDate datoTilOgMed) {
        if (datoFraOgMed.isAfter(datoTilOgMed)) {
            return List.of();
        }
        List<LocalDate> startDatoer = datoFraOgMed.datesUntil(datoTilOgMed.plusDays(1), Period.ofMonths(ANTALL_MÅNEDER_I_EN_PERIODE)).collect(Collectors.toList());
        ArrayList<Periode> datoPar = new ArrayList<>();
        for (int i = 0; i < startDatoer.size(); i++) {
            // fra: Hvis startdato er lik datoFraOgMed, bruk denne, hvis ikke, bruk første datoen i mnd.
            LocalDate fra = startDatoer.get(i).equals(datoFraOgMed) ? startDatoer.get(i) : førsteDatoIMnd(startDatoer.get(i));
            // til: Hvis siste dag i mnd. er mindre enn datoTilOgMed, bruk siste dag i mnd, ellers bruk datoTilOgMed
            LocalDate til = sisteDatoIMnd(startDatoer.get(i)).isBefore(datoTilOgMed) ? sisteDatoIMnd(startDatoer.get(i)) : datoTilOgMed;

            datoPar.addAll(splittHvisNyttÅr(fra, til));
        }
        // Legg til siste periode hvis den ikke kom med i loopen
        if (datoPar.get(datoPar.size() - 1).getSlutt() != datoTilOgMed) {
            datoPar.addAll(splittHvisNyttÅr(førsteDatoIMnd(datoTilOgMed), datoTilOgMed));
        }
        return datoPar;
    }

    private LocalDate førsteDatoIMnd(LocalDate dato) {
        return LocalDate.of(dato.getYear(), dato.getMonth(), 01);
    }

    private static List<Periode> splittHvisNyttÅr (LocalDate fraDato, LocalDate tilDato) {
        if (fraDato.getYear() != tilDato.getYear()) {
            Periode datoPar1 = new Periode(fraDato, fraDato.withMonth(12).withDayOfMonth(31));
            Periode datoPar2 = new Periode(tilDato.withMonth(1).withDayOfMonth(1), tilDato);
            return List.of(datoPar1, datoPar2);
        } else {
            return List.of(new Periode(fraDato, tilDato));
        }
    }
}

@Entity
@Data
@NoArgsConstructor
@RequiredArgsConstructor
@AllArgsConstructor(access = AccessLevel.PRIVATE)
@EqualsAndHashCode(onlyExplicitlyIncluded = true)
@Builder(toBuilder = true)
public class TilskuddPeriode implements Comparable<TilskuddPeriode> {

    @Id
    @EqualsAndHashCode.Include
    private UUID id = UUID.randomUUID();

    @ManyToOne
    @JoinColumn(name = "avtale_id")
    @JsonIgnore
    @ToString.Exclude
    private Avtale avtale;

    @NonNull
    private Integer beløp;
    @NonNull
    private LocalDate startDato;
    @NonNull
    private LocalDate sluttDato;

    @Convert(converter = NavIdentConverter.class)
    private NavIdent godkjentAvNavIdent;

    private LocalDateTime godkjentTidspunkt;

    private String enhet;
    private String enhetsnavn;

    @NonNull
    private Integer lonnstilskuddProsent;

    @Enumerated(EnumType.STRING)
    @ElementCollection(fetch = FetchType.LAZY)
    private Set<Avslagsårsak> avslagsårsaker = EnumSet.noneOf(Avslagsårsak.class);

    private String avslagsforklaring;
    @Convert(converter = NavIdentConverter.class)
    private NavIdent avslåttAvNavIdent;
    private LocalDateTime avslåttTidspunkt;
    private Integer løpenummer = 1;

    @Enumerated(EnumType.STRING)
    private TilskuddPeriodeStatus status = TilskuddPeriodeStatus.UBEHANDLET;

    @Enumerated(EnumType.STRING)
    private RefusjonStatus refusjonStatus = null;

    private boolean aktiv = true;

    public TilskuddPeriode deaktiverOgLagNyUbehandlet() {
        this.aktiv = false;
        TilskuddPeriode kopi = new TilskuddPeriode();
        kopi.id = UUID.randomUUID();
        kopi.løpenummer = this.løpenummer;
        kopi.beløp = this.beløp;
        kopi.lonnstilskuddProsent = this.lonnstilskuddProsent;
        kopi.startDato = this.startDato;
        kopi.sluttDato = this.sluttDato;
        kopi.avtale = this.avtale;
        kopi.aktiv = true;
        kopi.status = TilskuddPeriodeStatus.UBEHANDLET;
        return kopi;
    }

    private void sjekkOmKanBehandles() {
        if (status != TilskuddPeriodeStatus.UBEHANDLET) {
            throw new FeilkodeException(Feilkode.TILSKUDDSPERIODE_ER_ALLEREDE_BEHANDLET);
        }
        if (Now.localDate().isBefore(kanBesluttesFom())) {
            throw new FeilkodeException(Feilkode.TILSKUDDSPERIODE_BEHANDLE_FOR_TIDLIG);
        }
    }

    @JsonProperty
    private LocalDate kanBesluttesFom() {
        // TODO: DENNE KODEN MÅ FJERNES NÅR VI FÅR BESKJED OM AT DET ER OK Å HOLDE AV PENGER FOR NESTE ÅR
        if (LocalDate.now().getYear() == 2023 && startDato.getYear() == 2024) {
            if (startDato.minusMonths(3).getYear() == 2023) {
                // Setter kun 01-01-2024 hvis den opprinnelig hadde blitt satt til 2023.
                return LocalDate.of(2024, 01, 1);
            }
        }

        if (løpenummer == 1) {
            return LocalDate.MIN;
        }
        return startDato.minusMonths(3);
    }

    void godkjenn(NavIdent beslutter, String enhet) {
        sjekkOmKanBehandles();

        setGodkjentTidspunkt(Now.localDateTime());
        setGodkjentAvNavIdent(beslutter);
        setEnhet(enhet);
        setStatus(TilskuddPeriodeStatus.GODKJENT);
    }

    void avslå(NavIdent beslutter, EnumSet<Avslagsårsak> avslagsårsaker, String avslagsforklaring) {
        sjekkOmKanBehandles();
        if (avslagsforklaring.isBlank()) {
            throw new FeilkodeException(Feilkode.TILSKUDDSPERIODE_AVSLAGSFORKLARING_PAAKREVD);
        }
        if (avslagsårsaker.isEmpty()) {
            throw new FeilkodeException(Feilkode.TILSKUDDSPERIODE_INGEN_AVSLAGSAARSAKER);
        }

        setAvslåttTidspunkt(Now.localDateTime());
        setAvslåttAvNavIdent(beslutter);
        this.avslagsårsaker.addAll(avslagsårsaker);
        setAvslagsforklaring(avslagsforklaring);
        setStatus(TilskuddPeriodeStatus.AVSLÅTT);
    }

    public boolean kanBehandles() {
        try {
            sjekkOmKanBehandles();
            return true;
        } catch (FeilkodeException e) {
            return false;
        }
    }

    @Override
    public int compareTo(@NotNull TilskuddPeriode o) {
        return new CompareToBuilder()
                .append(this.getStartDato(), o.getStartDato())
                .append(this.isAktiv(), o.isAktiv())
                .append(this.getStatus(), o.getStatus())
                .append(this.getId(), o.getId())
                .toComparison();
    }

    public boolean erUtbetalt() {
        return refusjonStatus == RefusjonStatus.UTBETALT || refusjonStatus == RefusjonStatus.KORRIGERT;
    }

    public boolean erRefusjonGodkjent() {
        return refusjonStatus == RefusjonStatus.SENDT_KRAV || refusjonStatus == RefusjonStatus.GODKJENT_MINUSBELØP || refusjonStatus == RefusjonStatus.GODKJENT_NULLBELØP;
    }

}

public enum TilskuddPeriodeStatus {
    ANNULLERT, GODKJENT, AVSLÅTT, UBEHANDLET, BEHANDLET_I_ARENA
}

public enum Tiltakstype {
    ARBEIDSTRENING("Arbeidstrening", "ab0422", "ARBTREN"),
    MIDLERTIDIG_LONNSTILSKUDD("Midlertidig lønnstilskudd", "ab0336", "MIDLONTIL"),
    VARIG_LONNSTILSKUDD("Varig lønnstilskudd", "ab0337", "VARLONTIL"),
    MENTOR("Mentor", "ab0416", "MENTOR"),
    INKLUDERINGSTILSKUDD("Inkluderingstilskudd", "ab0417", "INKLUTILS"),
    SOMMERJOBB("Sommerjobb", "ab0450", null);

    final String beskrivelse;
    final String behandlingstema;
    final String tiltakskodeArena;

    Tiltakstype(String beskrivelse, String behandlingstema, String tiltakskodeArena) {
        this.beskrivelse = beskrivelse;
        this.behandlingstema = behandlingstema;
        this.tiltakskodeArena = tiltakskodeArena;
    }

    public String getBeskrivelse() {
        return this.beskrivelse;
    }

    public String getBehandlingstema() {
        return this.behandlingstema;
    }

    public String getTiltakskodeArena() {
        return tiltakskodeArena;
    }
}

@Slf4j
public class Veileder extends Avtalepart<NavIdent> implements InternBruker {
    private final TilgangskontrollService tilgangskontrollService;

    private final PersondataService persondataService;
    private final SlettemerkeProperties slettemerkeProperties;
    private final boolean harAdGruppeForBeslutter;
    private final Norg2Client norg2Client;
    private final Set<NavEnhet> navEnheter;
    private final VeilarbArenaClient veilarbArenaClient;
    private final UUID azureOid;

    public Veileder(
            NavIdent identifikator,
            UUID azureOid,
            TilgangskontrollService tilgangskontrollService,
            PersondataService persondataService,
            Norg2Client norg2Client,
            Set<NavEnhet> navEnheter,
            SlettemerkeProperties slettemerkeProperties,
            boolean harAdGruppeForBeslutter,
            VeilarbArenaClient veilarbArenaClient
    ) {

        super(identifikator);
        this.azureOid = azureOid;
        this.tilgangskontrollService = tilgangskontrollService;
        this.persondataService = persondataService;
        this.norg2Client = norg2Client;
        this.navEnheter = navEnheter;
        this.slettemerkeProperties = slettemerkeProperties;
        this.harAdGruppeForBeslutter = harAdGruppeForBeslutter;
        this.veilarbArenaClient = veilarbArenaClient;
    }

    @Deprecated
    public Veileder(
            NavIdent identifikator,
            TilgangskontrollService tilgangskontrollService,
            PersondataService persondataService,
            Norg2Client norg2Client,
            Set<NavEnhet> navEnheter,
            SlettemerkeProperties slettemerkeProperties,
            boolean harAdGruppeForBeslutter,
            VeilarbArenaClient veilarbArenaClient
    ) {
        this(identifikator, null, tilgangskontrollService, persondataService, norg2Client, navEnheter, slettemerkeProperties, harAdGruppeForBeslutter, veilarbArenaClient);
    }

    @Override
    public boolean harTilgangTilAvtale(Avtale avtale) {
        boolean harTilgang = tilgangskontrollService.harSkrivetilgangTilKandidat(this, avtale.getDeltakerFnr());
        if(!harTilgang) {
            log.info("Har ikke tilgang til avtale {}", avtale.getAvtaleNr());
        }
        return harTilgang;
    }

    @Override
    Page<Avtale> hentAlleAvtalerMedMuligTilgang(AvtaleRepository avtaleRepository, AvtalePredicate queryParametre, Pageable pageable) {
        NavIdent veilederNavIdent = queryParametre.getVeilederNavIdent() != null ? queryParametre.getVeilederNavIdent() : getIdentifikator();

        if(queryParametre.getStatus() != null) {
            // Har filtrert på status. Da går siste filtrering på status i java-kode
            Pageable allPages = PageRequest.of(0, Integer.MAX_VALUE, pageable.getSort());
            Page<Avtale> avtalerUtenStatusFiltrering = null;
            if(queryParametre.getTiltakstype() != null) {
                // Filtrer på tiltakstype
                if (queryParametre.getVeilederNavIdent() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByVeilederNavIdentAndTiltakstype(queryParametre.getVeilederNavIdent(), queryParametre.getTiltakstype(), allPages);
                } else if (queryParametre.getDeltakerFnr() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByDeltakerFnrAndTiltakstype(queryParametre.getDeltakerFnr(), queryParametre.getTiltakstype(), allPages);
                } else if (queryParametre.getBedriftNr() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByBedriftNrAndTiltakstype(queryParametre.getBedriftNr(), queryParametre.getTiltakstype(), allPages);
                } else if (queryParametre.getNavEnhet() != null && queryParametre.getErUfordelt() != null && queryParametre.getErUfordelt()) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByVeilederNavIdentIsNullAndEnhetGeografiskAndTiltakstypeOrVeilederNavIdentIsNullAndEnhetOppfolgingAndTiltakstype(queryParametre.getNavEnhet(), queryParametre.getTiltakstype(), queryParametre.getNavEnhet(), queryParametre.getTiltakstype(), allPages);
                } else if (queryParametre.getNavEnhet() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByEnhetGeografiskAndTiltakstypeOrEnhetOppfolgingAndTiltakstype(queryParametre.getNavEnhet(), queryParametre.getTiltakstype(), queryParametre.getNavEnhet(), queryParametre.getTiltakstype(), allPages);
                } else if (queryParametre.getAvtaleNr() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByAvtaleNrAndTiltakstype(queryParametre.getAvtaleNr(), queryParametre.getTiltakstype(), allPages);
                } else {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByVeilederNavIdentAndTiltakstype(veilederNavIdent, queryParametre.getTiltakstype(), allPages);
                }
            } else {
                if (queryParametre.getVeilederNavIdent() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByVeilederNavIdent(queryParametre.getVeilederNavIdent(), allPages);
                } else if (queryParametre.getDeltakerFnr() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByDeltakerFnr(queryParametre.getDeltakerFnr(), allPages);
                } else if (queryParametre.getBedriftNr() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByBedriftNr(queryParametre.getBedriftNr(), allPages);
                } else if (queryParametre.getNavEnhet() != null && queryParametre.getErUfordelt() != null && queryParametre.getErUfordelt()) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByVeilederNavIdentIsNullAndEnhetGeografiskOrVeilederNavIdentIsNullAndEnhetOppfolging(queryParametre.getNavEnhet(), queryParametre.getNavEnhet(), allPages);
                } else if (queryParametre.getNavEnhet() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByEnhetGeografiskOrEnhetOppfolging(queryParametre.getNavEnhet(), queryParametre.getNavEnhet(), allPages);
                } else if (queryParametre.getAvtaleNr() != null) {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByAvtaleNr(queryParametre.getAvtaleNr(), allPages);
                } else {
                    avtalerUtenStatusFiltrering = avtaleRepository.findAllByVeilederNavIdent(veilederNavIdent, allPages);
                }
            }
            int skip = pageable.getPageNumber() > 0 ? (pageable.getPageNumber())*pageable.getPageSize() : 0;
            List<Avtale> totaltFørPaging = avtalerUtenStatusFiltrering.getContent().stream()
                    .filter(avtale -> avtale.statusSomEnum() == queryParametre.getStatus()).toList();
            List<Avtale> avtaler = avtalerUtenStatusFiltrering.getContent().stream()
                    .filter(avtale -> avtale.statusSomEnum() == queryParametre.getStatus())
                    .skip(skip)
                    .limit(pageable.getPageSize()).toList();
            return new PageImpl<>(avtaler, pageable, totaltFørPaging.size());
        }
        else {
            // Har ikke filtrert på status. Da går all filtrering i JPA/database
            // Om det er filter med tiltaksType
            if(queryParametre.getTiltakstype() != null) {
                if (queryParametre.getVeilederNavIdent() != null) {
                    return avtaleRepository.findAllByVeilederNavIdentAndTiltakstype(queryParametre.getVeilederNavIdent(), queryParametre.getTiltakstype(), pageable);
                } else if (queryParametre.getDeltakerFnr() != null) {
                    return avtaleRepository.findAllByDeltakerFnrAndTiltakstype(queryParametre.getDeltakerFnr(), queryParametre.getTiltakstype(), pageable);
                } else if (queryParametre.getBedriftNr() != null) {
                    return avtaleRepository.findAllByBedriftNrAndTiltakstype(queryParametre.getBedriftNr(), queryParametre.getTiltakstype(), pageable);
                } else if (queryParametre.getNavEnhet() != null && queryParametre.getErUfordelt() != null && queryParametre.getErUfordelt()) {
                    return avtaleRepository.findAllByVeilederNavIdentIsNullAndEnhetGeografiskAndTiltakstypeOrVeilederNavIdentIsNullAndEnhetOppfolgingAndTiltakstype(queryParametre.getNavEnhet(), queryParametre.getTiltakstype(), queryParametre.getNavEnhet(), queryParametre.getTiltakstype(), pageable);
                } else if (queryParametre.getNavEnhet() != null) {
                    return avtaleRepository.findAllByEnhetGeografiskAndTiltakstypeOrEnhetOppfolgingAndTiltakstype(queryParametre.getNavEnhet(), queryParametre.getTiltakstype(), queryParametre.getNavEnhet(), queryParametre.getTiltakstype(), pageable);
                } else if (queryParametre.getAvtaleNr() != null) {
                    return avtaleRepository.findAllByAvtaleNrAndTiltakstype(queryParametre.getAvtaleNr(), queryParametre.getTiltakstype(), pageable);
                } else {
                    return avtaleRepository.findAllByVeilederNavIdentAndTiltakstype(veilederNavIdent, queryParametre.getTiltakstype(), pageable);
                }
            } else {
                // Ingen tiltakstyper i query
                if (queryParametre.getVeilederNavIdent() != null) {
                    return avtaleRepository.findAllByVeilederNavIdent(queryParametre.getVeilederNavIdent(), pageable);
                } else if (queryParametre.getDeltakerFnr() != null) {
                    return avtaleRepository.findAllByDeltakerFnr(queryParametre.getDeltakerFnr(), pageable);
                } else if (queryParametre.getBedriftNr() != null) {
                    return avtaleRepository.findAllByBedriftNr(queryParametre.getBedriftNr(), pageable);
                } else if (queryParametre.getNavEnhet() != null && queryParametre.getErUfordelt() != null && queryParametre.getErUfordelt()) {
                    return avtaleRepository.findAllByVeilederNavIdentIsNullAndEnhetGeografiskOrVeilederNavIdentIsNullAndEnhetOppfolging(queryParametre.getNavEnhet(), queryParametre.getNavEnhet(), pageable);
                } else if (queryParametre.getNavEnhet() != null) {
                    return avtaleRepository.findAllByEnhetGeografiskOrEnhetOppfolging(queryParametre.getNavEnhet(), queryParametre.getNavEnhet(), pageable);
                } else if (queryParametre.getAvtaleNr() != null) {
                    return avtaleRepository.findAllByAvtaleNr(queryParametre.getAvtaleNr(), pageable);
                } else {
                    return avtaleRepository.findAllByVeilederNavIdent(veilederNavIdent, pageable);
                }
            }
        }
    }

