public interface AvtaleInnholdStrategy {
    void endre(EndreAvtale endreAvtale);
    default void endreTilskuddsberegning(EndreTilskuddsberegning endreTilskuddsberegning) {
        throw new RuntimeException("Ikke implementert");
    }
    default void endreAvtaleInnholdMedKvalifiseringsgruppe(EndreAvtale endreAvtale, Kvalifiseringsgruppe kvalifiseringsgruppe) {}
    default void regnUtTotalLonnstilskudd() {}

    default void reUtregnRedusertProsentOgSum() {}
    Map<String, Object> alleFelterSomMåFyllesUt();

    void endreSluttDato(LocalDate nySluttDato);
}

@UtilityClass
public class AvtaleInnholdStrategyFactory {
    public AvtaleInnholdStrategy create(AvtaleInnhold avtaleInnhold, Tiltakstype tiltakstype) {
        switch (tiltakstype) {
            case ARBEIDSTRENING:
                return new ArbeidstreningStrategy(avtaleInnhold);
            case MIDLERTIDIG_LONNSTILSKUDD:
                return new MidlertidigLonnstilskuddStrategy(avtaleInnhold);
            case VARIG_LONNSTILSKUDD:
                return new VarigLonnstilskuddStrategy(avtaleInnhold);
            case MENTOR:
                return new MentorStrategy(avtaleInnhold);
            case INKLUDERINGSTILSKUDD:
                return new InkluderingstilskuddStrategy(avtaleInnhold);
            case SOMMERJOBB:
                return new SommerjobbStrategy(avtaleInnhold);
        }
        throw new IllegalStateException();
    }
}

public enum AvtaleInnholdType {
    INNGÅ, LÅSE_OPP, FORLENGE, FORKORTE, ENDRE_MÅL, ENDRE_INKLUDERINGSTILSKUDD, ENDRE_OM_MENTOR, ENDRE_TILSKUDDSBEREGNING, ENDRE_STILLING, ENDRE_KONTAKTINFO, ENDRE_OPPFØLGING_OG_TILRETTELEGGING, ANNULLERE
}

