public class MentorStartOgSluttDatoStrategy implements StartOgSluttDatoStrategy {
    private final Kvalifiseringsgruppe kvalifiseringsgruppe;

    public MentorStartOgSluttDatoStrategy(Kvalifiseringsgruppe kvalifiseringsgruppe) {
        this.kvalifiseringsgruppe = kvalifiseringsgruppe;
    }

    @Override
    public void sjekkStartOgSluttDato(LocalDate startDato, LocalDate sluttDato, boolean erGodkjentForEtterregistrering, boolean erAvtaleInngått) {
        StartOgSluttDatoStrategy.super.sjekkStartOgSluttDato(startDato, sluttDato, erGodkjentForEtterregistrering, erAvtaleInngått);

        if (startDato != null && sluttDato != null) {
            if ((kvalifiseringsgruppe == Kvalifiseringsgruppe.SPESIELT_TILPASSET_INNSATS || kvalifiseringsgruppe == Kvalifiseringsgruppe.VARIG_TILPASSET_INNSATS)
                    && startDato.plusMonths(36).minusDays(1).isBefore(sluttDato)) {
                throw new FeilkodeException(Feilkode.VARIGHET_FOR_LANG_MENTOR_36_MND);
            }
        }

        if (kvalifiseringsgruppe != Kvalifiseringsgruppe.SPESIELT_TILPASSET_INNSATS && kvalifiseringsgruppe != Kvalifiseringsgruppe.VARIG_TILPASSET_INNSATS && startDato != null && sluttDato != null && startDato.plusMonths(6).minusDays(1).isBefore(sluttDato)) {
            throw new FeilkodeException(Feilkode.VARIGHET_FOR_LANG_MENTOR_6_MND);
        }
    }
}

public class MidlertidigLonnstilskuddStartOgSluttDatoStrategy implements StartOgSluttDatoStrategy {
    private static final int TJUEFIRE_MND_MAKS_LENGDE = 24;
    private static final int TOLV_MND_MAKS_LENGDE = 12;
    private final Kvalifiseringsgruppe kvalifiseringsgruppe;

    MidlertidigLonnstilskuddStartOgSluttDatoStrategy(Kvalifiseringsgruppe kvalifiseringsgruppe) {
        this.kvalifiseringsgruppe = kvalifiseringsgruppe;
    }

    @Override
    public void sjekkStartOgSluttDato(LocalDate startDato, LocalDate sluttDato, boolean erGodkjentForEtterregistrering, boolean erAvtaleInngått) {
        StartOgSluttDatoStrategy.super.sjekkStartOgSluttDato(startDato, sluttDato, erGodkjentForEtterregistrering, erAvtaleInngått);

        if (startDato != null && sluttDato != null) {
            if ((kvalifiseringsgruppe == Kvalifiseringsgruppe.SPESIELT_TILPASSET_INNSATS || kvalifiseringsgruppe == Kvalifiseringsgruppe.VARIG_TILPASSET_INNSATS)
                    && startDato.plusMonths(TJUEFIRE_MND_MAKS_LENGDE).minusDays(1).isBefore(sluttDato)) {
                throw new FeilkodeException(Feilkode.VARIGHET_FOR_LANG_MIDLERTIDIG_LONNSTILSKUDD_24_MND);
            }

            if (kvalifiseringsgruppe == Kvalifiseringsgruppe.SITUASJONSBESTEMT_INNSATS && startDato.plusMonths(TOLV_MND_MAKS_LENGDE).minusDays(1).isBefore(sluttDato)) {
                throw new FeilkodeException(Feilkode.VARIGHET_FOR_LANG_MIDLERTIDIG_LONNSTILSKUDD_12_MND);
            }

            // Ikke funnet kvalifiseringsgruppe, default 12 mnd
            if (kvalifiseringsgruppe == null && startDato.plusMonths(TOLV_MND_MAKS_LENGDE).minusDays(1).isBefore(sluttDato)) {
                throw new FeilkodeException(Feilkode.VARIGHET_FOR_LANG_MIDLERTIDIG_LONNSTILSKUDD_12_MND);
            }
        }
    }
}

public class SommerjobbStartOgSluttDatoStrategy implements StartOgSluttDatoStrategy {
    @Override
    public void sjekkStartOgSluttDato(LocalDate startDato, LocalDate sluttDato, boolean erGodkjentForEtterregistrering, boolean erAvtaleInngått) {
        StartOgSluttDatoStrategy.super.sjekkStartOgSluttDato(startDato, sluttDato, erGodkjentForEtterregistrering, erAvtaleInngått);
        if (startDato != null) {
                if (startDato.isBefore(LocalDate.of(startDato.getYear(), 6, 1)) ) {
                    throw new FeilkodeException(Feilkode.SOMMERJOBB_FOR_TIDLIG);
                }
                if (startDato.isAfter(LocalDate.of(startDato.getYear(), 8, 31))) {
                    throw new FeilkodeException(Feilkode.SOMMERJOBB_FOR_SENT);
                }
        }
      if (startDato != null && sluttDato != null) {
        if (startDato.plusWeeks(4).minusDays(1).isBefore(sluttDato)) {
          throw new FeilkodeException(Feilkode.SOMMERJOBB_FOR_LANG_VARIGHET);
        }else{
          if (sluttDato.isBefore(LocalDate.of(sluttDato.getYear(), 6, 1)) ) {
            throw new FeilkodeException(Feilkode.SOMMERJOBB_FOR_TIDLIG);
          }
          if (sluttDato.isAfter(LocalDate.of(sluttDato.getYear(), 9, 27))) {
            throw new FeilkodeException(Feilkode.SOMMERJOBB_FOR_SENT);
          }
        }
      }
    }
}

public interface StartOgSluttDatoStrategy {
    default void sjekkStartOgSluttDato(LocalDate startDato, LocalDate sluttDato, boolean erGodkjentForEtterregistrering, boolean erAvtaleInngått) {
        if (startDato != null && sluttDato != null && startDato.isAfter(sluttDato)) {
            throw new FeilkodeException(Feilkode.START_ETTER_SLUTT);
        }
        if (startDato != null && sluttDato != null && !erGodkjentForEtterregistrering && startDato.plusDays(7).isBefore(Now.localDate()) && !erAvtaleInngått){
            throw new FeilkodeException(Feilkode.FORTIDLIG_STARTDATO);
        }
        if (startDato != null && sluttDato != null && sluttDato.isAfter(LocalDate.of(2089, 12, 31))) {
            throw new FeilkodeException(Feilkode.SLUTTDATO_GRENSE_NÅDD);
        }
    }
}

